let token="",me=null,myAllowedShift=null;if("serviceWorker" in navigator)navigator.serviceWorker.register("/sw.js").catch(()=>{});function bsApply(root){if(!root.querySelectorAll)return;root.querySelectorAll("button:not(.btn)").forEach(b=>b.classList.add("btn",b.classList.contains("secondary")?"btn-outline-secondary":b.classList.contains("danger")?"btn-danger":"btn-primary"));root.querySelectorAll("table:not(.table)").forEach(t=>t.classList.add("table","table-hover","align-middle","mb-0"));root.querySelectorAll("input:not(.form-control),select:not(.form-select),textarea:not(.form-control)").forEach(e=>e.classList.add(e.tagName==="SELECT"?"form-select":"form-control"));}bsApply(document);new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.nodeType===1)bsApply(n)}).observe(document.body,{childList:true,subtree:true});const $=id=>document.getElementById(id);const api=async(path,opts={})=>{let r=await fetch("/api"+path,{...opts,headers:{"content-type":"application/json","authorization":"Bearer "+token,...opts.headers}});let d=await r.json();if(!r.ok)throw Error(d.error||"Request gagal");return d};
