if(url.pathname==="/api/password"&&req.method==="POST"){const b=await req.json();if(typeof b.current_password!=="string"||typeof b.new_password!=="string"||!b.current_password||!b.new_password)return json({error:"Data tidak lengkap"},400);if(b.current_password.length>128||b.new_password.length>128)return json({error:"Terlalu panjang"},400);if(b.new_password.length<8)return json({error:"Password baru minimal 8 karakter"},400);const u=await env.DB.prepare("SELECT password_hash,salt FROM users WHERE id=?").bind(user.id).first();if(!u||await hashPassword(b.current_password,u.salt)!==u.password_hash)return json({error:"Password saat ini salah"},401);const h=await makeHash(b.new_password);await env.DB.prepare("UPDATE users SET password_hash=?,salt=? WHERE id=?").bind(h.hash,h.salt,user.id).run();return json({ok:true});}
