if(url.pathname==="/api/admin/shifts"&&req.method==="POST"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const b=await req.json();if(!b.name||!/^\d{2}:\d{2}$/.test(b.start_time)||!/^\d{2}:\d{2}$/.test(b.end_time))return json({error:"Nama dan jam shift wajib valid"},400);await env.DB.prepare("INSERT INTO shifts(name,start_time,end_time) VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET start_time=excluded.start_time,end_time=excluded.end_time").bind(b.name,b.start_time,b.end_time).run();return json({ok:true});}
