if(url.pathname==="/api/admin/monthly"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const month=url.searchParams.get("month")||wibToday().slice(0,7);const rows=(await env.DB.prepare("SELECT c.*,u.name,s.name AS shift_name FROM checklists c JOIN users u ON u.id=c.user_id LEFT JOIN shifts s ON s.id=c.shift_id WHERE substr(c.date,1,7)=? ORDER BY c.date,u.name,c.kind").bind(month).all()).results;return json({reports:rows.map(r=>({id:r.id,name:r.name,date:r.date,kind:r.kind,shift_name:r.shift_name,status:r.status||"Sudah Diisi",follow_up_note:r.follow_up_note||"",values:JSON.parse(r.values_json),sesi:r.sesi||1,count:Object.keys(JSON.parse(r.values_json)).length}))});}
if(url.pathname==="/api/admin/history"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const date=url.searchParams.get("date")||"";const kind=url.searchParams.get("kind")||"";const rows=(await env.DB.prepare("SELECT h.*,u.name,s.name AS shift_name FROM checklist_history h JOIN users u ON u.id=h.user_id LEFT JOIN shifts s ON s.id=h.shift_id WHERE (?='' OR h.date=?) AND (?='' OR h.kind=?) ORDER BY h.changed_at DESC LIMIT 500").bind(date,date,kind,kind).all()).results;return json({history:rows});}
if(url.pathname==="/api/checklists"&&req.method==="POST"){if(user.role!=="user")return json({error:"Hanya user yang dapat mengisi checklist"},403);const b=await req.json();if(!b.date||!b.kind||!b.values||typeof b.values!=="object")return json({error:"Data tidak lengkap"},400);if(!/^\d{4}-\d{2}-\d{2}$/.test(b.date))return json({error:"Format tanggal tidak valid"},400);if(!KINDS.includes(b.kind))return json({error:"Jenis checklist tidak valid"},400);if(b.status!==undefined&&!STATUSES.includes(b.status))return json({error:"Status checklist tidak valid"},400);const status=b.status||"Sudah Diisi";const note=typeof b.follow_up_note==="string"?b.follow_up_note.slice(0,500):"";const entries=Object.entries(b.values);if(entries.length>200)return json({error:"Terlalu banyak item (maks. 200)"},400);for(const[k,v]of entries){if(typeof k!=="string"||!k.trim()||k.length>200||(typeof v!=="string"&&typeof v!=="number")||String(v).length>300)return json({error:"Nilai item tidak valid (maks. 300 karakter)"},400)}const shift=await env.DB.prepare("SELECT * FROM shifts WHERE id=?").bind(b.shift_id||0).first();if(!shift)return json({error:"Pilih shift yang valid"},400);const au=await env.DB.prepare("SELECT u.allowed_shift_id,s.name AS allowed_name FROM users u LEFT JOIN shifts s ON s.id=u.allowed_shift_id WHERE u.id=?").bind(user.id).first();if(au&&au.allowed_shift_id&&shift.id!==au.allowed_shift_id)return json({error:"Akun Anda hanya diizinkan mengisi checklist pada "+(au.allowed_name||"shift tertentu")},403);const sesi=Number(b.sesi)||1;if(![1,2,3].includes(sesi))return json({error:"Sesi harus 1, 2, atau 3"},400);const now=new Date();const hhmm=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Jakarta",hour:"2-digit",minute:"2-digit",hour12:false}).format(now);const inWindow=shift.start_time<=shift.end_time?(hhmm>=shift.start_time&&hhmm<=shift.end_time):(hhmm>=shift.start_time||hhmm<=shift.end_time);if(!inWindow)return json({error:`Jam pengisian di luar jadwal ${shift.name} (${shift.start_time}-${shift.end_time} WIB)`},403);const old=await env.DB.prepare("SELECT values_json,status,follow_up_note,shift_id,sesi FROM checklists WHERE user_id=? AND date=? AND kind=? AND sesi=?").bind(user.id,b.date,b.kind,sesi).first();const changedAt=now.toISOString();const oldValues=old?JSON.parse(old.values_json):{};const changedItems=[...new Set([...Object.keys(oldValues),...Object.keys(b.values)])].filter(k=>String(oldValues[k]??"")!==String(b.values[k]??""));const noChange=old&&changedItems.length===0&&old.status===status&&(old.follow_up_note||"")===note&&old.shift_id===shift.id;const summary=noChange?"Disimpan ulang tanpa perubahan":old?(changedItems.length?"Parameter berubah: "+changedItems.slice(0,20).join(", "):"Tidak ada perubahan nilai")+"; status "+(old.status||"Sudah Diisi")+" → "+status:"Checklist baru dibuat";await env.DB.prepare("INSERT INTO checklists(user_id,date,kind,values_json,created_at,shift_id,status,follow_up_note,sesi) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id,date,kind,sesi) DO UPDATE SET values_json=excluded.values_json,created_at=excluded.created_at,shift_id=excluded.shift_id,status=excluded.status,follow_up_note=excluded.follow_up_note").bind(user.id,b.date,b.kind,JSON.stringify(b.values),changedAt,shift.id,status,note,sesi).run();if(!noChange)await env.DB.prepare("INSERT INTO checklist_history(user_id,date,kind,shift_id,status,change_summary,old_values_json,new_values_json,changed_at,sesi) VALUES(?,?,?,?,?,?,?,?,?,?)").bind(user.id,b.date,b.kind,shift.id,status,summary,JSON.stringify(oldValues),JSON.stringify(b.values),changedAt,sesi).run();return json({ok:true});}
if(url.pathname==="/api/admin/trends"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);
const rows=(await env.DB.prepare("SELECT substr(date,1,7) AS month,status,COUNT(*) AS n FROM checklists WHERE date>=date('now','+7 hours','-5 months','start of month') GROUP BY substr(date,1,7),status ORDER BY month").all()).results;
const userCount=await env.DB.prepare("SELECT COUNT(*) AS n FROM users WHERE role='user'").first();
const map=new Map();for(const r of rows){if(!map.has(r.month))map.set(r.month,{month:r.month,filled:0,follow:0,missing:0});const x=map.get(r.month);if(r.status==="Perlu Tindak Lanjut")x.follow+=r.n;else x.filled+=r.n;}
const now=new Date();for(let i=5;i>=0;i--){const dt=new Date(now.getFullYear(),now.getMonth()-i,1);const month=dt.toISOString().slice(0,7);if(!map.has(month))map.set(month,{month,filled:0,follow:0,missing:0});const x=map.get(month);const days=(month===new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit'}).format(now))?Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',day:'2-digit'}).format(now)):new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate();x.missing=Math.max(0,(userCount.n||0)*days*3-x.filled-x.follow);}
return json({trends:[...map.values()].sort((a,b)=>a.month.localeCompare(b.month))});}
if(url.pathname==="/api/admin/summary"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const date=url.searchParams.get("date")||wibToday();const users=(await env.DB.prepare("SELECT id,name,username,role FROM users ORDER BY role,name").all()).results;const rows=(await env.DB.prepare("SELECT c.id,c.user_id,u.name,c.date,c.kind,c.values_json,c.status,s.name AS shift_name,c.follow_up_note,c.sesi FROM checklists c JOIN users u ON u.id=c.user_id LEFT JOIN shifts s ON s.id=c.shift_id WHERE c.date=? ORDER BY u.name,c.kind").bind(date).all()).results;const reports=rows.map(r=>({id:r.id,user_id:r.user_id,name:r.name,date:r.date,kind:r.kind,values:JSON.parse(r.values_json),status:r.status||"Sudah Diisi",shift_name:r.shift_name,follow_up_note:r.follow_up_note||"",sesi:r.sesi||1,count:Object.keys(JSON.parse(r.values_json)).length}));return json({users,reports,todayCount:reports.length,submittedUsers:new Set(reports.map(r=>r.user_id)).size});}
if(url.pathname==="/api/admin/shift-status"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const date=url.searchParams.get("date")||wibToday();const shiftId=Number(url.searchParams.get("shift_id"))||0;const shift=await env.DB.prepare("SELECT * FROM shifts WHERE id=?").bind(shiftId).first();if(!shift)return json({error:"Shift tidak ditemukan"},400);const sched=(await env.DB.prepare("SELECT u.id,u.name FROM schedules s JOIN users u ON u.id=s.user_id WHERE s.date=? AND s.shift_id=? ORDER BY u.name").bind(date,shiftId).all()).results;const users=sched.length?sched:(await env.DB.prepare("SELECT id,name FROM users WHERE role='user' AND (allowed_shift_id IS NULL OR allowed_shift_id=?) ORDER BY name").bind(shiftId).all()).results;const rows=(await env.DB.prepare("SELECT user_id,sesi,kind FROM checklists WHERE date=? AND shift_id=? GROUP BY user_id,sesi,kind").bind(date,shiftId).all()).results;const map=new Map();for(const r of rows){if(!map.has(r.user_id))map.set(r.user_id,new Map());map.get(r.user_id).set(r.sesi+"|"+r.kind,true)}const out=users.map(u=>{const m=map.get(u.id)||new Map();const missing=[];for(const s of[1,2,3])for(const k of KINDS){if(!m.has(s+"|"+k))missing.push({sesi:s,kind:k})}return{id:u.id,name:u.name,filled:KINDS.length*3-missing.length,missing}});return json({date,shift:{name:shift.name,start_time:shift.start_time,end_time:shift.end_time},users:out,scheduled:!!sched.length});}
if(url.pathname==="/api/admin/daily-trend"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const days=Math.min(60,Math.max(7,Number(url.searchParams.get("days"))||14));const end=wibToday();const start=addDays(end,-(days-1));const rows=(await env.DB.prepare("SELECT date,COUNT(*) AS n,SUM(CASE WHEN status='Perlu Tindak Lanjut' THEN 1 ELSE 0 END) AS follow,COUNT(DISTINCT user_id) AS users FROM checklists WHERE date>=? GROUP BY date ORDER BY date").bind(start).all()).results;return json({start:start,end:end,days:days,rows:rows});}
if(url.pathname==="/api/admin/schedule"&&req.method==="POST"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const b=await req.json();const shiftId=Number(b.shift_id);const ids=[...new Set((b.user_ids||[]).map(Number).filter(Boolean))];const days=Math.min(62,Math.max(1,Number(b.days)||30));const start=/^\d{4}-\d{2}-\d{2}$/.test(b.start_date||"")?b.start_date:wibToday();if(!shiftId||!ids.length)return json({error:"Pilih shift dan minimal 1 user"},400);const sh=await env.DB.prepare("SELECT * FROM shifts WHERE id=?").bind(shiftId).first();if(!sh)return json({error:"Shift tidak ditemukan"},400);const stmts=[env.DB.prepare("DELETE FROM schedules WHERE shift_id=? AND date>=? AND date<=?").bind(shiftId,start,addDays(start,days-1))];for(let i=0;i<days;i++){const uid=ids[i%ids.length];stmts.push(env.DB.prepare("INSERT INTO schedules (user_id,shift_id,date) VALUES (?,?,?)").bind(uid,shiftId,addDays(start,i)))}await env.DB.batch(stmts);return json({ok:true,shift:sh.name,start:start,end:addDays(start,days-1),days:days,users:ids.length});}
if(url.pathname==="/api/admin/schedule"&&req.method==="DELETE"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const b=await req.json();const shiftId=Number(b.shift_id);const days=Math.min(62,Math.max(1,Number(b.days)||30));const dsp=b.start_date;const start=/^\d{4}-\d{2}-\d{2}$/.test(dsp||"")?dsp:wibToday();if(!shiftId)return json({error:"Pilih shift"},400);await env.DB.prepare("DELETE FROM schedules WHERE shift_id=? AND date>=? AND date<=?").bind(shiftId,start,addDays(start,days-1)).run();return json({ok:true});}
if(url.pathname==="/api/admin/schedule"&&req.method==="GET"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const days=Math.min(62,Math.max(1,Number(url.searchParams.get("days"))||30));const sp=url.searchParams.get("start");const start=/^\d{4}-\d{2}-\d{2}$/.test(sp||"")?sp:wibToday();const rows=(await env.DB.prepare("SELECT s.date,s.shift_id,s.user_id,u.name AS user_name FROM schedules s JOIN users u ON u.id=s.user_id WHERE s.date>=? AND s.date<=? ORDER BY s.date,s.shift_id").bind(start,addDays(start,days-1)).all()).results;const shifts=(await env.DB.prepare("SELECT id,name,start_time,end_time FROM shifts ORDER BY id").all()).results;return json({start:start,days:days,today:wibToday(),shifts:shifts,rows:rows});}
if(url.pathname==="/api/my-schedule"){const today=wibToday();const rows=(await env.DB.prepare("SELECT s.date,sh.name AS shift_name,sh.start_time,sh.end_time FROM schedules s JOIN shifts sh ON sh.id=s.shift_id WHERE s.user_id=? AND s.date>=? ORDER BY s.date,s.shift_id LIMIT 60").bind(user.id,today).all()).results;return json({today:today,schedule:rows});}
