if(url.pathname==="/api/admin/users"&&req.method==="POST"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);const b=await req.json();if(!b.name||!b.username||!b.password||b.password.length<8)return json({error:"Nama, username, dan password minimal 8 karakter wajib diisi"},400);if(!["user","admin"].includes(b.role))return json({error:"Role tidak valid"},400);let allowed=null;if(b.allowed_shift_id){const sh=await env.DB.prepare("SELECT id FROM shifts WHERE id=?").bind(Number(b.allowed_shift_id)).first();if(!sh)return json({error:"Shift pembatas tidak ditemukan"},400);allowed=Number(b.allowed_shift_id)}const h=await makeHash(b.password);try{await env.DB.prepare("INSERT INTO users(name,username,password_hash,salt,role,allowed_shift_id) VALUES(?,?,?,?,?,?)").bind(b.name,b.username,h.hash,h.salt,b.role,allowed).run();return json({ok:true})}catch{return json({error:"Username sudah digunakan"},409)}}
const del=url.pathname.match(/^\/api\/admin\/users\/(\d+)$/);if(del&&req.method==="DELETE"){if(user.role!=="admin")return json({error:"Akses admin diperlukan"},403);if(Number(del[1])===user.id)return json({error:"Tidak dapat menghapus akun sendiri"},400);await env.DB.batch([env.DB.prepare("DELETE FROM schedules WHERE user_id=?").bind(del[1]),env.DB.prepare("DELETE FROM checklist_history WHERE user_id=?").bind(del[1]),env.DB.prepare("DELETE FROM checklists WHERE user_id=?").bind(del[1]),env.DB.prepare("DELETE FROM users WHERE id=?").bind(del[1])]);return json({ok:true});}
